    up: {"bbc": "BBC-ludo", "wecDaily": "Ĉiutaga WeCup-ludo — sen aliĝo", "wecFinal": "Monata finalo de WeCup", "wecGrand": "Granda finalo de WeCup", "mc": "Monthly Cup"}
