    bbcLinks: "<a href=\"https://bbc.pokerth.net/registration\">കലണ്ടറും സൈൻ അപ്പും</a> · <a href=\"https://bbc.pokerth.net/results\">ഫലങ്ങൾ</a> · <a href=\"https://bbc.pokerth.net/results/ranking\">റാങ്കിംഗ്</a>",
    wecH2: "WeCup (WEC)",
